WITH p AS (SELECT coalesce(%s::text,'') mold_code,coalesce(%s::text,'') trang_thai,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY m.mold_code) stt,m.mold_code,m.mold_name,m.mold_name2,m.cavity,m.setting_time,m.status,m.date0,m.time0,m.date2,m.time2,count(*) OVER() total FROM public.mfdmkhuon m CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.mold_code='' OR m.mold_code=ANY(string_to_array(s.mold_code,','))) AND (s.trang_thai='' OR m.status=s.trang_thai) ORDER BY m.mold_code LIMIT (SELECT lim FROM p);
